function closestDivisors(num) {
  // Divisors pair up around the square root, so the closest pair uses the largest divisor not above it.
  const closestPair = n => {
    for (let small = Math.floor(Math.sqrt(n)); small >= 1; small--) {
      if (n % small === 0) {
        return [small, n / small];
      }
    }
  };

  const first = closestPair(num + 1);
  const second = closestPair(num + 2);
  if (first[1] - first[0] <= second[1] - second[0]) {
    return first;
  }
  return second;
}

