function closestDivisors(num) {
  // Walk every divisor a of both numbers from 1 upward and keep the pair with the smallest gap.
  let best = null;
  for (const n of [num + 1, num + 2]) {
    for (let a = 1; a * a <= n; a++) {
      if (n % a !== 0) continue;
      const b = n / a;
      if (best === null || b - a < best[1] - best[0]) best = [a, b];
    }
  }
  return best;
}

